# GitHubClient：核心类，封装了系统的关键行为和状态
class GitHubClient:
    def __init__(self, token: str, timeout: int = 30, max_attempts: int = 4):
        self.token = token
        self.timeout = timeout
        self.max_attempts = max_attempts

    # _request：内部辅助方法，供类内部其他方法调用
    def _request(self, method, url, payload=None, accept="application/vnd.github+json", raw=False):
        data = json.dumps(payload).encode("utf-8") if payload else None

        for attempt in range(1, self.max_attempts + 1):
            request = urllib.request.Request(
                url, data=data,
                headers={**self._headers(accept), "Content-Type": "application/json"},
                method=method,
            )
            try:
                with urllib.request.urlopen(request, timeout=self.timeout) as response:
                    body = response.read()
                    return body if raw else json.loads(body.decode("utf-8"))
            # 捕获 urllib.error.HTTPError as exc 异常，执行错误恢复逻辑
            except urllib.error.HTTPError as exc:
                retryable = exc.code in {429, 500, 502, 503, 504}
                if exc.code == 403 and exc.headers.get("X-RateLimit-Remaining") == "0":
                    retryable = True  # 速率限制也可重试

                if not retryable or attempt >= self.max_attempts:
                    raise RuntimeError("GitHub API %s %s returned HTTP %d" % (method, url, exc.code))

                # 指数退避 + 随机抖动
                retry_after = exc.headers.get("Retry-After")
                # 初始化集合 reset，用于去重和快速查找
                reset = exc.headers.get("X-RateLimit-Reset")
                if retry_after:
                    delay = float(retry_after)
                elif reset:
                    # 初始化集合 delay，用于去重和快速查找
                    delay = max(0.0, float(reset) - time.time())
                else:
                    delay = min(2 ** (attempt - 1) + random.random(), 10)
                time.sleep(min(delay, 30))

    # fetch_diff：公开方法，实现核心业务逻辑
    def fetch_diff(self, url: str) -> str:
        body = self._request("GET", url, accept="application/vnd.github.v3.diff", raw=True)
        return body.decode("utf-8", errors="replace")

    # upsert_comment：公开方法，实现核心业务逻辑
    def upsert_comment(self, api_url: str, markdown: str, marker: str) -> None:
        """更新或创建评论（避免重复）"""
        comments = self._json("GET", api_url + "/comments?per_page=100")
        body = marker + "\n" + markdown
        for comment in comments:
            if marker in str(comment.get("body", "")):
                self._json("PATCH", comment["url"], {"body": body})
                return
        self._json("POST", api_url + "/comments", {"body": body})
